INSERT INTO `forum_posts` VALUES (1,1,1,'chao-mung-den-voi-army-3-web','Chào mừng đến với cổng thông tin Army 3','Nơi cập nhật sự kiện, theo dõi nhân vật và giao lưu cùng cộng đồng.','Cổng thông tin Army 3 đã chính thức mở cửa. Bạn có thể đăng ký tài khoản, xem nhân vật, theo dõi bảng xếp hạng và tham gia thảo luận tại diễn đàn.',1502,1,0,0,'2026-08-12 16:13:18','2026-08-12 16:13:18'),(2,2,1,'huong-dan-chien-dich-hai-toa-thap','Hướng dẫn chiến dịch Hai Tòa Tháp','Phối hợp đồng đội, xử lý cảm tử và kết thúc round đúng điều kiện.','Giữ đội hình, ưu tiên cảm tử khi chúng áp sát và tiêu diệt toàn bộ boss để chiến thắng. Kinh nghiệm hạ bot bắt đầu từ 200 và tăng thêm 10 cho mỗi mục tiêu tiếp theo.',1516,0,0,0,'2026-08-12 16:13:18','2026-08-12 16:13:18');
/*!40000 ALTER TABLE `forum_posts` ENABLE KEYS */;
UNLOCK TABLES;

