INSERT INTO `game_events` VALUES (1,'hai-toa-thap-2026','Chiến dịch Hai Tòa Tháp','Hạ phiến quân và đội cảm tử để nhận kinh nghiệm tăng dần theo số mục tiêu.','Tập hợp đồng đội, bảo vệ toàn bộ người chơi và tiêu diệt hết boss trên bản đồ Hai Tòa Tháp. Cảm tử sẽ truy đuổi mục tiêu gần nhất và chỉ kích nổ khi đã áp sát.',1516,'2026-08-11 17:00:00','2026-09-12 16:59:59',1,1,'2026-08-12 16:13:18','2026-08-12 16:13:18'),(2,'le-hoi-halloween-2026','Lễ hội Halloween 2026','Thu thập bí ngô, mở quà giới hạn và chinh phục bảng xếp hạng sự kiện.','Lễ hội bắt đầu từ ngày 20 tháng 10. Hoàn thành nhiệm vụ mỗi ngày để nhận vật phẩm trang trí và phần thưởng kinh nghiệm.',1978,'2026-10-19 17:00:00','2026-11-02 16:59:59',0,1,'2026-08-12 16:13:18','2026-08-12 16:13:18');
/*!40000 ALTER TABLE `game_events` ENABLE KEYS */;
UNLOCK TABLES;

